// Shared memory between the fbtcal SteamVR driver and the calibrator app.
// Layout is mirrored in app/shm.py — keep both in sync.
#pragma once
#include <cstdint>

#define FBTCAL_SHM_NAME "/fbtcal-v1"
#define FBTCAL_MAGIC 0x46425431u  // "FBT1"
#define FBTCAL_MAX_DEVICES 64
#define FBTCAL_MAX_SLOTS 8

enum FbtcalMode : uint32_t {
	FBTCAL_PASSTHROUGH = 0,
	FBTCAL_OFFSET = 1,    // final = real * offset (device-local)
	FBTCAL_OVERRIDE = 2,  // final = override pose (raw world), only while app heartbeat is fresh
};

#pragma pack(push, 8)
struct FbtcalSlot {           // written by app
	char serial[64];
	uint32_t mode;
	uint32_t _pad;
	double offPos[3];
	double offRot[4];         // w x y z
	double ovPos[3];
	double ovRot[4];
};

struct FbtcalRaw {            // written by driver, real pose before any change (raw world)
	uint32_t seq;             // seqlock: odd while writing
	uint32_t valid;
	uint64_t timeNs;          // CLOCK_MONOTONIC
	double pos[3];
	double rot[4];            // w x y z
};

struct FbtcalShared {
	uint32_t magic;
	uint32_t appGen;          // seqlock over slots: odd while app writes
	uint64_t appHeartbeatNs;  // CLOCK_MONOTONIC, refreshed by app
	uint64_t driverHeartbeatNs;
	FbtcalSlot slots[FBTCAL_MAX_SLOTS];
	FbtcalRaw raw[FBTCAL_MAX_DEVICES];
};
#pragma pack(pop)
